recipes.code:
{
  "inputs": [
    {
      "id": "halalterminal-api-key",
      "type": "promptString",
      "description": "Halal Terminal API key (prefix ht_). Free tier available at https://api.halalterminal.com — email-only signup, no credit card.",
      "password": true
    }
  ],
  "servers": {
    "mcp": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@halalterminal/mcp@1.0.0"
      ],
      "env": {
        "HALALTERMINAL_API_KEY": "${input:halalterminal-api-key}"
      }
    }
  }
}
